INSERT INTO `question_options` VALUES (1,1,'A','1.024 tingkat',0),(2,1,'B','4.096 tingkat',1),(3,1,'C','4.095 tingkat',0),(4,1,'D','8.192 tingkat',0),(5,2,'A','Kalibrasi mengganti masukan analog menjadi sinyal PWM.',0),(6,2,'B','Kalibrasi memastikan seluruh ADC memiliki jumlah kanal yang sama.',0),(7,2,'C','Kalibrasi mengubah setiap GPIO menjadi masukan analog.',0),(8,2,'D','Kalibrasi mengompensasi variasi karakteristik, termasuk tegangan referensi chip.',1),(9,3,'A','Agar jalur open-drain dapat kembali ke logika tinggi saat dilepas.',1),(10,3,'B','Agar setiap perangkat selalu memperoleh alamat baru.',0),(11,3,'C','Agar kecepatan bus selalu tepat 1 MHz.',0),(12,3,'D','Agar arah komunikasi berubah menjadi full-duplex.',0),(13,4,'A','0x50, setelah alamat digeser untuk menyisipkan bit tulis.',0),(14,4,'B','0x51, setelah alamat digeser dan ditambahkan bit baca.',0),(15,4,'C','0x28, tanpa menyertakan bit baca/tulis.',1),(16,4,'D','0x29, agar berbeda dari alamat perangkat.',0),(17,5,'A','20%',0),(18,5,'B','25%',1),(19,5,'C','50%',0),(20,5,'D','75%',0),(21,6,'A','ledc_update_duty()',1),(22,6,'B','ledc_get_duty()',0),(23,6,'C','ledc_timer_pause()',0),(24,6,'D','ledc_fade_func_uninstall()',0),(25,7,'A','Menaikkan frekuensi dan resolusi secara bersamaan.',0),(26,7,'B','Memindahkan nilai duty ke luar rentang resolusinya.',0),(27,7,'C','Menghapus pemeriksaan error tanpa mengubah konfigurasi.',0),(28,7,'D','Menurunkan frekuensi atau resolusi duty hingga kombinasi didukung.',1),(29,8,'A','Mengaktifkan pull-up internal GPIO34 tanpa komponen eksternal.',0),(30,8,'B','Mengubah GPIO34 menjadi keluaran push-pull saat tombol dilepas.',0),(31,8,'C','Menggunakan GPIO34 sebagai input dengan resistor pull-up eksternal.',1),(32,8,'D','Mengaktifkan pull-down internal lalu membalik nama variabel.',0),(33,9,'A','Mutex yang diambil sebelum akses dan dilepas sesudahnya.',1),(34,9,'B','Variabel penanda biasa yang diakses tanpa sinkronisasi.',0),(35,9,'C','Penundaan tetap pada kedua task tanpa pen