rbeda dari sumber.',0),(112,28,'D','Menghapus metadata sumber sebelum mengambil digest.',0),(113,29,'A','Menghapus file berbahaya sebelum pengambilan image.',0),(114,29,'B','Mencegah komputer akuisisi menulis ke media sumber.',1),(115,29,'C','Mengenkripsi seluruh salinan secara otomatis.',0),(116,29,'D','Memulihkan semua data terhapus tanpa analisis.',0),(117,30,'A','Memberikan izin baca pada laporan yang diperlukan tanpa izin perubahan.',1),(118,30,'B','Memberikan hak administrator agar semua menu tersedia.',0),(119,30,'C','Menggunakan akun bersama dengan hak penuh.',0),(120,30,'D','Memberikan izin hapus karena akun sudah memiliki izin baca.',0),(121,25,'A','27',0),(122,25,'B','32',0),(123,25,'C','62',0),(124,25,'D','30',1);
