/*!40000 ALTER TABLE `questions` DISABLE KEYS */;
INSERT INTO `questions` VALUES (1,1,'REF-ES-01-001',1,'Sebuah ADC dikonfigurasi pada resolusi 12 bit. Berapa banyak tingkat kuantisasi yang tersedia?','Jumlah tingkat kuantisasi adalah 2^12 = 4.096; kode keluarannya bernilai 0 sampai 4.095.\n\nTopik: Resolusi ADC. Tingkat rancangan: Dasar.\nSoal orisinal berbasis referensi; perlu peninjauan akademik sebelum publikasi.\nReferensi diperiksa: 2026-10-14.\n- Espressif — ESP32 ADC: Conversion, Attenuation and Calibration | ADC Conversion; ADC Attenuation\n  https://docs.espressif.com/projects/esp-idf/en/latest/esp32/api-reference/peripherals/adc.html','PUBLISHED','2026-10-16 17:14:09'),(2,1,'REF-ES-01-002',1,'Dua ESP32 membaca tegangan masukan yang sama tetapi menghasilkan estimasi tegangan sedikit berbeda. Mengapa kalibrasi ADC relevan?','Tegangan referensi aktual dapat berbeda antar-chip. Kalibrasi membantu mengubah pembacaan mentah menjadi estimasi tegangan yang lebih akurat.\n\nTopik: Kalibrasi ADC. Tingkat rancangan: Menengah.\nSoal orisinal berbasis referensi; perlu peninjauan akademik sebelum publikasi.\nReferensi diperiksa: 2026-10-14.\n- Espressif — ESP32 ADC: Conversion, Attenuation and Calibration | ADC Conversion; ADC Attenuation\n  https://docs.espressif.com/projects/esp-idf/en/latest/esp32/api-reference/peripherals/adc.html','PUBLISHED','2026-10-16 17:14:09'),(3,1,'REF-ES-01-003',1,'Mengapa jalur SDA dan SCL pada bus I2C memerlukan resistor pull-up?','Keluaran open-drain menarik jalur ke rendah; resistor pull-up membawa jalur kembali ke tinggi ketika tidak ditarik oleh perangkat.\n\nTopik: Bus I2C. Tingkat rancangan: Dasar.\nSoal orisinal berbasis referensi; perlu peninjauan akademik sebelum publikasi.\nReferensi diperiksa: 2026-10-14.\n- Espressif — ESP32 Inter-Integrated Circuit (I2C) | Introduction; Install I2C master bus and device\n  https://docs.espressif.com/projects/esp-idf/en/stable/esp32/api-reference/peripherals/i2c.html','PUBLISHED','2026-10-16 17:14:09'),(4,1,'REF-ES-01-004',1,'Sebuah sensor memiliki alamat I2C 7 bit 0x28. Nilai apa yang diisikan ke device_address pada driver master I2C ESP-IDF?','device_address menerima alamat mentah perangkat, tanpa bit baca/tulis. Untuk sensor ini nilainya tetap 0x28.\n\nTopik: Pengalamatan I2C. Tingkat rancangan: Menengah.\nSoal orisinal berbasis referensi; perlu peninjauan akademik sebelum publikasi.\nReferensi diperiksa: 2026-10-14.\n- Espressif — ESP32 Inter-Integrated Circuit (I2C) | Introduction; Install I2C master bus and device\n  https://docs.espressif.com/projects/esp-idf/en/stable/esp32/api-reference/peripherals/i2c.html','PUBLISHED','2026-10-16 17:14:09'),(5,1,'REF-ES-01-005',1,'Sinyal PWM memiliki periode 2 ms dan waktu aktif 0,5 ms. Berapa duty cycle-nya?','Duty cycle = waktu aktif / periode × 100% = 0,5 / 2 × 100% = 25%.\n\nTopik: Perhitungan PWM. Tingkat rancangan: Menengah.\nSoal orisinal berbasis referensi; perlu peninjauan akademik sebelum publikasi.\nReferensi diperiksa: 2026-10-14.\n- Espressif — ESP32 LED Control (LEDC) | Change PWM Duty Cycle Using Software; Supported Range of Frequency and Duty Resolutions\n  https://docs.espressif.com/projects/esp-idf/en/stable/esp32/api-reference/peripherals/ledc.html','PUBLISHED','2026-10-16 17:14:09'),(6,1,'REF-ES-01-006',1,'Pada API LEDC ESP-IDF, program memanggil ledc_set_duty() untuk mengubah duty cycle. Pemanggilan apa yang mengaktifkan pembaruan tersebut?','Pada pasangan API ini, ledc_set_duty() menyiapkan nilai baru dan ledc_update_duty() menerapkan pembaruannya.\n\nTopik: Pembaruan PWM. Tingkat rancangan: Menengah.\nSoal orisinal berbasis referensi; perlu peninjauan akademik sebelum publikasi.\nReferensi diperiksa: 2026-10-14.\n- Espressif — ESP32 LED Control (LEDC) | Change PWM Duty Cycle Using Software; Supported Range of Frequency and Duty Resolutions\n  https://docs.espressif.com/projects/esp-idf/en/stable/esp32/api-reference/peripherals/ledc.html','PUBLISHED','2026-10-16 17:14:09'),(7,1,'REF-ES-01-007',1,'Driver LEDC menolak kombinasi frekuensi dan resolusi duty karena melampaui kemampuan hardware. Tindakan mana yang sesuai?','Frekuensi dan resolusi duty dibatasi clock serta pembagi timer. Kombinasi yang terlalu tinggi perlu dikurangi.\n\nTopik: Batas konfigurasi PWM. Tingkat rancangan: Menengah.\nSoal orisinal berbasis referensi; perlu peninjauan akademik sebelum publikasi.\nReferensi diperiksa: 2026-10-14.\n- Espressif — ESP32 LED Control (LEDC) | Change PWM Duty Cycle Using Software; Supported Range of Frequency and Duty Resolutions\n  https://docs.espressif.com/projects/esp-idf/en/stable/esp32/api-reference/peripherals/ledc.html','PUBLISHED','2026-10-16 17:14:09'),(8,1,'REF-ES-01-008',1,'Pada ESP32 klasik, tombol dihubungkan ke GPIO34 dan membutuhkan bias pull-up. Pilihan rancangan mana yang tepat?','GPIO34-39 pada ESP32 klasik hanya mendukung input dan tidak memiliki pull-up/pull-down internal yang dapat diaktifkan melalui perangkat lunak.\n\nTopik: Pemilihan GPIO. Tingkat rancangan: Menengah.\nSoal orisinal berbasis referensi; perlu peninjauan akademik sebelum publikasi.\nReferensi diperiksa: 2026-10-14.\n- Espressif — ESP32 GPIO & RTC GPIO | GPIO summary and notes: GPIO34-39\n  https://docs.espressif.com/projects/esp-idf/en/stable/esp32/api-reference/peripherals/gpio.html','PUBLISHED','2026-10-16 17:14:09'),(9,1,'REF-ES-01-009',1,'Dua task FreeRTOS harus memakai satu periferal secara bergantian. Mekanisme mana yang paling sesuai untuk mutual exclusion sederhana?','Mutex melindungi sumber daya bersama dan memiliki priority inheritance untuk mengurangi dampak priority inversion; mutex digunakan dari task, bukan ISR.\n\nTopik: Sinkronisasi RTOS. Tingkat rancangan: Menengah.\nSoal orisinal berbasis referensi; perlu peninjauan akademik sebelum publikasi.\nReferensi diperiksa: 2026-10-14.\n- FreeRTOS — Mutexes | FreeRTOS Mutexes; Simplified priority inheritance\n  https://freertos.org/Real-time-embedded-RTOS-mutexes.html','PUBLISHED','2026-10-16 17:14:09'),(10,1,'REF-ES-01-010',1,'Sebuah task ESP32 menjalankan loop panjang tanpa yielding sehingga idle task tidak mendapat waktu CPU. Mekanisme apa yang mendeteksi kondisi ini?','TWDT yang memantau idle task dapat mendeteksi task yang berjalan terlalu lama tanpa yielding.\n\nTopik: Task watchdog. Tingkat rancangan: Menengah.\nSoal orisinal berbasis referensi; perlu peninjauan akademik sebelum publikasi.\nReferensi diperiksa: 2026-10-14.\n- Espressif — ESP32 Watchdogs | Overview; Task Watchdog Timer (TWDT)\n  https://docs.espressif.com/projects/esp-idf/en/stable/esp32/api-reference/system/wdts.html','PUBLISHED','2026-10-16 17:14:09'),(11,2,'REF-SC-02-001',1,'Dataset akan dibagi menjadi data latih dan uji. Urutan penggunaan StandardScaler mana yang menghindari kebocoran data?','Statistik preprocessing dipelajari hanya dari data latih. Data uji ditransformasi dengan statistik yang sama.\n\nTopik: Pencegahan data leakage. Tingkat rancangan: Menengah.\nSoal orisinal berbasis referensi; perlu peninjauan akademik sebelum publikasi.\nReferensi diperiksa: 2026-10-14.\n- scikit-learn — Common pitfalls and recommended practices | Inconsistent preprocessing; Data leakage; How to avoid data leakage\n  https://scikit-learn.org/stable/common_pitfalls.html','PUBLISHED','2026-10-16 17:14:09'),(12,2,'REF-SC-02-002',1,'Mengapa scaler dan estimator sebaiknya dimasukkan ke Pipeline saat cross-validation?','Pipeline membantu memastikan langkah preprocessing hanya dipelajari dari bagian latih pada setiap fold.\n\nTopik: Pipeline dan validasi. Tingkat rancangan: Menengah.\nSoal orisinal berbasis referensi; perlu peninjauan akademik sebelum publikasi.\nReferensi diperiksa: 2026-10-14.\n- scikit-learn — Common pitfalls and recommended practices | Inconsistent preprocessing; Data leakage; How to avoid data leakage\n  https://scikit-learn.org/stable/common_pitfalls.html','PUBLISHED','2026-10-16 17:14:09'),(13,2,'REF-SC-02-003',1,'Dengan StandardScaler default, rata-rata fitur pada data latih adalah 10 dan simpangan bakunya 2. Berapa hasil transformasi nilai 14?','Standardisasi menggunakan z = (x - rata-rata) / simpangan baku = (14 - 10) / 2 = 2.\n\nTopik: Standardisasi fitur. Tingkat rancangan: Menengah.\nSoal orisinal berbasis referensi; perlu peninjauan akademik sebelum publikasi.\nReferensi diperiksa: 2026-10-14.\n- scikit-learn — StandardScaler | Standard score z = (x - u) / s\n  https://scikit-learn.org/stable/modules/generated/sklearn.preprocessing.StandardScaler.html','PUBLISHED','2026-10-16 17:14:09'),(14,2,'REF-SC-02-004',1,'Klasifikasi biner menghasilkan TP = 30, FP = 10, dan FN = 20. Berapa precision kelas positif?','Precision = TP / (TP + FP) = 30 / 40 = 75%. FN digunakan untuk recall, bukan penyebut precision.\n\nTopik: Precision. Tingkat rancangan: Menengah.\nSoal orisinal berbasis referensi; perlu peninjauan akademik sebelum publikasi.\nReferensi diperiksa: 2026-10-14.\n- scikit-learn — Metrics and scoring | Precision, recall and F-measures / Binary classification\n  https://scikit-learn.org/stable/modules/model_evaluation.html','PUBLISHED','2026-10-16 17:14:09'),(15,2,'REF-SC-02-005',1,'Dari 50 sampel positif aktual, model berhasil mendeteksi 40 dan melewatkan 10. Berapa recall kelas positif?','Recall = TP / (TP + FN) = 40 / (40 + 10) = 80%.\n\nTopik: Recall. Tingkat rancangan: Menengah.\nSoal orisinal berbasis referensi; perlu peninjauan akademik sebelum publikasi.\nReferensi diperiksa: 2026-10-14.\n- scikit-learn — Metrics and scoring | Precision, recall and F-measures / Binary classification\n  https://scikit-learn.org/stable/modules/model_evaluation.html','PUBLISHED','2026-10-16 17:14:09'),(16,2,'REF-SC-02-006',1,'Pada 5-fold cross-validation biasa, bagaimana setiap fold digunakan untuk validasi?','K-fold membagi data menjadi k bagian; setiap bagian bergiliran menjadi validasi, dengan k-1 bagian lain untuk pelatihan.\n\nTopik: K-fold cross-validation. Tingkat rancangan: Dasar.\nSoal orisinal berbasis referensi; perlu peninjauan akademik sebelum publikasi.\nReferensi diperiksa: 2026-10-14.\n- scikit-learn — Cross-validation: evaluating estimator performance | K-fold; Stratified K-fold; Time series split\n  https://scikit-learn.org/stable/modules/cross_validation.html','PUBLISHED','2026-10-16 17:14:09'),(17,2,'REF-SC-02-007',1,'Dataset klasifikasi memiliki kelas yang tidak seimbang. Apa tujuan StratifiedKFold?','Stratifikasi berusaha menjaga proporsi kelas pada tiap fold; prosedur ini bukan teknik penyeimbangan jumlah sampel.\n\nTopik: Stratifikasi kelas. Tingkat rancangan: Menengah.\nSoal orisinal berbasis referensi; perlu peninjauan akademik sebelum publikasi.\nReferensi diperiksa: 2026-10-14.\n- scikit-learn — Cross-validation: evaluating estimator performance | K-fold; Stratified K-fold; Time series split\n  https://scikit-learn.org/stable/modules/cross_validation.html','PUBLISHED','2026-10-16 17:14:09'),(18,2,'REF-SC-02-008',1,'Apa fungsi objektif utama yang diminimalkan K-means?','K-means meminimalkan inertia atau within-cluster sum of squares terhadap centroid terdekat.\n\nTopik: K-means. Tingkat rancangan: Dasar.\nSoal orisinal berbasis referensi; perlu peninjauan akademik sebelum publikasi.\nReferensi diperiksa: 2026-10-14.\n- scikit-learn — Clustering | K-means\n  https://scikit-learn.org/stable/modules/clustering.html','PUBLISHED','2026-10-16 17:14:09'),(19,2,'REF-SC-02-009',1,'Decision tree sangat akurat pada data latih tetapi jauh lebih buruk pada validasi. Langkah mana yang dapat membantu mengendalikan overfitting?','Membatasi kedalaman mengendalikan kompleksitas pohon. Dampaknya tetap perlu diperiksa pada data validasi.\n\nTopik: Kompleksitas decision tree. Tingkat rancangan: Menengah.\nSoal orisinal berbasis referensi; perlu peninjauan akademik sebelum publikasi.\nReferensi diperiksa: 2026-10-14.\n- scikit-learn — Decision Trees | Tips on practical use\n  https://scikit-learn.org/stable/modules/tree.html','PUBLISHED','2026-10-16 17:14:09'),(20,2,'REF-SC-02-010',1,'Model memprediksi nilai besok dari data historis. Pembagian validasi mana yang paling sesuai untuk menjaga urutan waktu?','TimeSeriesSplit mempertahankan urutan temporal sehingga data masa depan tidak masuk ke pelatihan untuk mengevaluasi periode sebelumnya.\n\nTopik: Validasi deret waktu. Tingkat rancangan: Menengah.\nSoal orisinal berbasis referensi; perlu peninjauan akademik sebelum publikasi.\nReferensi diperiksa: 2026-10-14.\n- scikit-learn — Cross-validation: evaluating estimator performance | K-fold; Stratified K-fold; Time series split\n  https://scikit-learn.org/stable/modules/cross_validation.html','PUBLISHED','2026-10-16 17:14:09'),(21,3,'REF-JDF-03-001',1,'Alamat IPv4 mana yang termasuk ruang alamat privat menurut RFC 1918?','Rentang privat mencakup 172.16.0.0 sampai 172.31.255.255; 172.20.10.5 berada di dalamnya.\n\nTopik: IPv4 privat. Tingkat rancangan: Dasar.\nSoal orisinal berbasis referensi; perlu peninjauan akademik sebelum publikasi.\nReferensi diperiksa: 2026-10-14.\n- IETF RFC 1918 — Address Allocation for Private Internets | 3. Private Address Space\n  https://www.rfc-editor.org/rfc/rfc1918','PUBLISHED','2026-10-16 17:14:09'),(22,3,'REF-JDF-03-002',1,'Dalam pembentukan koneksi TCP normal, klien mengirim SYN. Respons server berikutnya adalah apa?','Pada three-way handshake dasar, urutannya SYN, SYN-ACK, lalu ACK.\n\nTopik: TCP handshake. Tingkat rancangan: Dasar.\nSoal orisinal berbasis referensi; perlu peninjauan akademik sebelum publikasi.\nReferensi diperiksa: 2026-10-14.\n- IETF RFC 9293 — Transmission Control Protocol (TCP) | 3.5. Connection Establishment; Figure 6\n  https://www.rfc-editor.org/rfc/rfc9293','PUBLISHED','2026-10-16 17:14:09'),(23,3,'REF-JDF-03-003',1,'Jenis DNS record apa yang digunakan untuk memetakan nama host ke alamat IPv4?','A record berisi alamat host IPv4. MX untuk mail exchanger, CNAME untuk alias, dan PTR untuk pemetaan balik.\n\nTopik: DNS record. Tingkat rancangan: Dasar.\nSoal orisinal berbasis referensi; perlu peninjauan akademik sebelum publikasi.\nReferensi diperiksa: 2026-10-14.\n- IETF RFC 1035 — Domain names: implementation and specification | 3.2.2. TYPE values; 3.4.1. A RDATA format\n  https://www.rfc-editor.org/rfc/rfc1035','PUBLISHED','2026-10-16 17:14:09'),(24,3,'REF-JDF-03-004',1,'Apa perlindungan utama TLS untuk komunikasi aplikasi melalui jaringan?','TLS melindungi kanal komunikasi dari penyadapan dan perubahan pesan. Perlindungan data tersimpan serta otorisasi aplikasi memerlukan mekanisme tersendiri.\n\nTopik: Perlindungan TLS. Tingkat rancangan: Menengah.\nSoal orisinal berbasis referensi; perlu peninjauan akademik sebelum publikasi.\nReferensi diperiksa: 2026-10-14.\n- IETF RFC 8446 — The Transport Layer Security (TLS) Protocol Version 1.3 | Abstract; 1. Introduction\n  https://www.rfc-editor.org/rfc/rfc8446','PUBLISHED','2026-10-16 17:14:09'),(25,3,'REF-JDF-03-005',1,'Sebuah subnet IPv4 biasa menggunakan prefix /27. Dengan alamat network dan broadcast dicadangkan, berapa alamat host yang dapat digunakan?','Prefix /27 menyisakan 5 bit host: 2^5 = 32 alamat. Setelah network dan broadcast, tersedia 30 alamat host.\n\nTopik: Subnet CIDR. Tingkat rancangan: Menengah.\nSoal orisinal berbasis referensi; perlu peninjauan akademik sebelum publikasi.\nReferensi diperiksa: 2026-10-14.\n- IETF RFC 4632 — Classless Inter-domain Routing (CIDR) | 3.1. Basic Concept and Prefix Notation\n  https://www.rfc-editor.org/rfc/rfc4632','PUBLISHED','2026-10-16 17:14:09'),(26,3,'REF-JDF-03-006',1,'Aplikasi mencari akun berdasarkan input pengguna. Praktik mana yang paling tepat untuk mencegah input mengubah struktur SQL?','Query berparameter memisahkan struktur SQL dari data masukan sehingga nilai pengguna tidak ditafsirkan sebagai kode SQL.\n\nTopik: Pencegahan SQL injection. Tingkat rancangan: Menengah.\nSoal orisinal berbasis referensi; perlu peninjauan akademik sebelum publikasi.\nReferensi diperiksa: 2026-10-14.\n- OWASP — SQL Injection Prevention Cheat Sheet | Defense Option 1: Prepared Statements (with Parameterized Queries)\n  https://cheatsheetseries.owasp.org/cheatsheets/SQL_Injection_Prevention_Cheat_Sheet.html','PUBLISHED','2026-10-16 17:14:09'),(27,3,'REF-JDF-03-007',1,'Apa tujuan salt unik pada hashing password?','Salt unik menghambat penggunaan tabel prahitung dan membuat password identik menghasilkan hash berbeda; salt tidak perlu dirahasiakan.\n\nTopik: Salt password. Tingkat rancangan: Menengah.\nSoal orisinal berbasis referensi; perlu peninjauan akademik sebelum publikasi.\nReferensi diperiksa: 2026-10-14.\n- OWASP — Password Storage Cheat Sheet | Salting; Hashing vs Encryption\n  https://cheatsheetseries.owasp.org/cheatsheets/Password_Storage_Cheat_Sheet.html','PUBLISHED','2026-10-16 17:14:09'),(28,3,'REF-JDF-03-008',1,'Setelah membuat image forensik, bagaimana analis memeriksa kesesuaian integritas salinan terhadap sumber dengan hashing?','Perbandingan digest membantu memeriksa integritas salinan. Kecocokan hash bukan bukti identitas pembuat atau kelengkapan chain of custody.\n\nTopik: Integritas bukti digital. Tingkat rancangan: Menengah.\nSoal orisinal berbasis referensi; perlu peninjauan akademik sebelum publikasi.\nReferensi diperiksa: 2026-10-14.\n- NIST SP 800-86 — Guide to Integrating Forensic Techniques into Incident Response | 4.2.2. Data File Integrity (printed pp. 4-7–4-9)\n  https://nvlpubs.nist.gov/nistpubs/Legacy/SP/nistspecialpublication800-86.pdf','PUBLISHED','2026-10-16 17:14:09'),(29,3,'REF-JDF-03-009',1,'Apa fungsi utama write blocker saat mengambil image media penyimpanan untuk forensik?','Write blocker mencegah penulisan ke media sumber selama akuisisi untuk membantu menjaga bukti asli.\n\nTopik: Write blocker. Tingkat rancangan: Menengah.\nSoal orisinal berbasis referensi; perlu peninjauan akademik sebelum publikasi.\nReferensi diperiksa: 2026-10-14.\n- NIST SP 800-86 — Guide to Integrating Forensic Techniques into Incident Response | 4.2.2. Data File Integrity (printed pp. 4-7–4-9)\n  https://nvlpubs.nist.gov/nistpubs/Legacy/SP/nistspecialpublication800-86.pdf','PUBLISHED','2026-10-16 17:14:09'),(30,3,'REF-JDF-03-010',1,'Akun petugas hanya perlu membaca laporan. Pengaturan akses mana yang mengikuti prinsip least privilege?','Least privilege memberikan izin minimum yang diperlukan untuk tugas pengguna, termasuk pembatasan terhadap sumber daya yang dapat diakses.\n\nTopik: Least privilege. Tingkat rancangan: Menengah.\nSoal orisinal berbasis referensi; perlu peninjauan akademik sebelum publikasi.\nReferensi diperiksa: 2026-10-14.\n- OWASP — Authorization Cheat Sheet | Enforce Least Privileges\n  https://cheatsheetseries.owasp.org/cheatsheets/Authorization_Cheat_Sheet.html','PUBLISHED','2026-10-16 17:14:09');
